import json
def scan(o, path=""):
    bad=[]
    if isinstance(o, bool):
        bad.append((path,"bool"))
    elif isinstance(o, float):
        bad.append((path,"float"))
    elif isinstance(o, dict):
        for k,v in o.items(): bad+=scan(v, path+"."+str(k))
    elif isinstance(o, list):
        for i,v in enumerate(o): bad+=scan(v, path+"[%d]"%i)
    return bad
for f in ("tmp/dev/stress2_out.json","tmp/dev/big_out.json","tmp/dev/actual.json"):
    d=json.load(open(f))
    b=scan(d)
    txt=open(f).read()
    print(f, "non-int/bool issues:", len(b), b[:5], "| NaN/Inf tokens:", any(t in txt for t in ("NaN","Infinity")))
